WITH queue_state AS (
  SELECT count(*) FILTER (WHERE status = 'retry_wait')::integer AS retry_wait_count,
         count(*) FILTER (WHERE status = 'manual_review')::integer AS manual_review_count
  FROM video_classification_processing_state
), updated AS (
  UPDATE pipeline_runs run SET finished_at = coalesce(run.finished_at,current_timestamp),status = CASE WHEN run.items_failed > 0 AND run.items_processed = 0 THEN 'failed' WHEN run.items_failed > 0 THEN 'partial' ELSE 'success' END,duration_seconds = coalesce(run.duration_seconds,extract(epoch FROM (current_timestamp-run.started_at))),metadata = run.metadata || jsonb_build_object('candidates_selected',run.items_received,'classifications_created',run.items_processed,'classifications_skipped',run.items_skipped,'classifications_failed',run.items_failed,'model_calls_estimated',run.api_calls,'average_classification_seconds',CASE WHEN run.items_processed + run.items_failed > 0 THEN round((extract(epoch FROM (current_timestamp-run.started_at))/(run.items_processed+run.items_failed))::numeric,3) ELSE NULL END,'classifier_retry_wait_queue',queue_state.retry_wait_count,'classifier_manual_review_queue',queue_state.manual_review_count)
  FROM queue_state WHERE run.id = $1::bigint RETURNING run.*
)
SELECT id AS pipeline_run_id,workflow,status,items_received,items_processed,items_skipped,items_failed,api_calls,duration_seconds,metadata,started_at,finished_at FROM updated;

WITH args AS (
  SELECT $1::bigint AS run_id,$2::bigint AS video_id,$3::text AS model,$4::text AS prompt_version,$5::text AS category_slug,$6::text AS topic,$7::text AS content_type,$8::text AS format,$9::text AS hook_type,$10::text AS source_type,$11::text AS presentation_style,$12::numeric AS originality_score,$13::numeric AS copyright_risk,$14::numeric AS reused_content_risk,$15::numeric AS confidence
), inserted AS (
  INSERT INTO video_classifications (video_id,category_id,topic,content_type,format,hook_type,source_type,presentation_style,originality_score,copyright_risk,reused_content_risk,ai_confidence,classification_model,prompt_version)
  SELECT args.video_id,c.id,args.topic,args.content_type,args.format,args.hook_type,args.source_type,args.presentation_style,args.originality_score,args.copyright_risk,args.reused_content_risk,args.confidence,args.model,args.prompt_version
  FROM args LEFT JOIN categories c ON c.slug = nullif(args.category_slug,'unknown')
  ON CONFLICT (video_id) DO NOTHING RETURNING video_id
), completed AS (
  SELECT args.video_id,mark_classification_completed(args.video_id) AS state_closed FROM args
), updated AS (
  UPDATE pipeline_runs run SET items_processed = run.items_processed + CASE WHEN EXISTS (SELECT 1 FROM inserted) THEN 1 ELSE 0 END,items_skipped = run.items_skipped + CASE WHEN EXISTS (SELECT 1 FROM inserted) THEN 0 ELSE 1 END,api_calls = run.api_calls + 1
  FROM args CROSS JOIN completed WHERE run.id = args.run_id RETURNING run.*
)
SELECT updated.id AS pipeline_run_id,updated.items_processed,updated.items_skipped,updated.items_failed,args.video_id,EXISTS (SELECT 1 FROM inserted) AS classification_created,completed.state_closed AS reliability_state_closed FROM updated CROSS JOIN args CROSS JOIN completed;

