function parseObject(value) {
  if (value && typeof value === "object" && !Array.isArray(value)) return value;
  if (Array.isArray(value)) value = value.map((part) => typeof part === "string" ? part : (part?.text ?? part?.content ?? "")).join("\n");
  const text = String(value ?? "").trim(); const candidates = [text];
  for (const match of text.matchAll(/```(?:json)?\s*([\s\S]*?)```/gi)) candidates.push(match[1].trim());
  let depth = 0; let start = -1; let inString = false; let escaped = false;
  for (let i = 0; i < text.length; i++) { const char = text[i]; if (inString) { if (escaped) escaped = false; else if (char === "\\") escaped = true; else if (char === "\"") inString = false; continue; } if (char === "\"") { inString = true; continue; } if (char === "{") { if (depth === 0) start = i; depth++; } else if (char === "}" && depth > 0) { depth--; if (depth === 0 && start >= 0) candidates.push(text.slice(start, i + 1)); } }
  for (let i = candidates.length - 1; i >= 0; i--) { try { const parsed = JSON.parse(candidates[i]); if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) return parsed; } catch {} }
  throw new Error("Nemotron response does not contain a valid JSON object");
}
const parsed = parseObject($json.choices?.[0]?.message?.content ?? $json.text ?? $json.output ?? $json);
const categories = ["movie_tv_clips","podcast_clips","curiosities","technology","games","humor","quick_tutorials","sports","storytelling","motivation","unknown"];
const formats = ["explainer","curiosity","tutorial","storytelling","reaction","clip","ranking","news","meme","comparison","motivation","commentary","compilation","unknown"];
const hooks = ["question","curiosity_gap","controversy","surprising_fact","promise","fear","challenge","before_after","story","list","direct_statement","unknown"];
const sources = ["original","third_party_content","movie_or_tv_clip","podcast_clip","gameplay","stock_media","user_generated","compilation","reaction","unknown"];
const word = (name) => { const value = String(parsed[name] ?? "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, ""); return value || "unknown"; };
const enumValue = (name, allowed, aliases = {}) => { const rawValue = String(parsed[name] ?? "").trim(); const value = aliases[rawValue] ?? rawValue; if (!allowed.includes(value)) throw new Error(`Invalid ${name} in Nemotron response`); return value; };
const score = (name) => { let value = Number(parsed[name]); if (!Number.isFinite(value) || value < 0 || value > 100) throw new Error(`Invalid ${name} in Nemotron response`); if (value > 1) value /= 100; return value; };
return { json: { output: { category_slug: enumValue("category_slug", categories), topic: word("topic"), content_type: word("content_type"), format: enumValue("format", formats, { quick_tutorials: "tutorial", gameplay: "clip" }), hook_type: enumValue("hook_type", hooks), source_type: enumValue("source_type", sources), presentation_style: word("presentation_style"), originality_score: score("originality_score"), copyright_risk: score("copyright_risk"), reused_content_risk: score("reused_content_risk"), confidence: score("confidence") } } };
